(6486669, 964864, 108069, '<td valign="top">Clever. I had a similar idea in mind but couldn''t get it together. Creative and different shot.</td>', 'Clever. I had a similar idea in mind but couldn''t get it together. Creative and different shot.', '2011-08-01 09:26:53.000000', NULL, 1),
