(6487547, 964397, 108069, '<td valign="top">Rainier!* Excellent crop and presentation. Very nice.<br/> <br/>*Well it reminded me of Rainier, but I''m pretty sure it''s not (especially considering the winter comment).</td>', 'Rainier!* Excellent crop and presentation. Very nice. *Well it reminded me of Rainier, but I''m pretty sure it''s not (especially considering the winter comment).', '2011-08-01 19:38:00.000000', NULL, 1),
(6487550, 964132, 108069, '<td valign="top">Lovely image. Great composition and tones. Beautiful.</td>', 'Lovely image. Great composition and tones. Beautiful.', '2011-08-01 19:39:38.000000', NULL, 1),
(6487583, 964528, 16106, '<td valign="top">While I like the photograph better for them, the punched up dramatic clouds steal the eye away from the skyline. So ironically, better photo, worse entry.</td>', 'While I like the photograph better for them, the punched up dramatic clouds steal the eye away from the skyline. So ironically, better photo, worse entry.', '2011-08-01 20:17:40.000000', NULL, 1),
(6487602, 964487, 68020, '<td valign="top">great capture. Hope to get there some day - 8</td>', 'great capture. Hope to get there some day - 8', '2011-08-01 20:29:03.000000', NULL, 1),
(6487604, 964326, 68020, '<td valign="top">Awesome capture. My highest score so far - 9</td>', 'Awesome capture. My highest score so far - 9', '2011-08-01 20:33:09.000000', NULL, 1),
(6487605, 964317, 68020, '<td valign="top">OK..now THIS is my highest score so far! - 10</td>', 'OK..now THIS is my highest score so far! - 10', '2011-08-01 20:34:10.000000', NULL, 1),
(6487721, 964339, 30669, '<td valign="top">What an interesting title and composition. Very well done.   10</td>', 'What an interesting title and composition. Very well done.   10', '2011-08-01 21:48:05.000000', NULL, 1),
(6487758, 964985, 116631, '<td valign="top">almost abstract!</td>', 'almost abstract!', '2011-08-01 22:14:13.000000', NULL, 1),
(6487759, 964234, 116631, '<td valign="top">wow!!</td>', 'wow!!', '2011-08-01 22:14:24.000000', NULL, 1),
(6487927, 964488, 126371, '<td valign="top">Excellent photo. Is the horizon tilted a bit or is my eye tricking me?</td>', 'Excellent photo. Is the horizon tilted a bit or is my eye tricking me?', '2011-08-02 00:08:51.000000', NULL, 1),
(6487930, 964313, 126371, '<td valign="top">Perfect! Amazing light. It looks unreal, yet not too unreal...</td>', 'Perfect! Amazing light. It looks unreal, yet not too unreal...', '2011-08-02 00:09:56.000000', NULL, 1),
(6487932, 964684, 126371, '<td valign="top">That''s a cool photo. I do wonder if the reflected light on the far left is a bit distracting...</td>', 'That''s a cool photo. I do wonder if the reflected light on the far left is a bit distracting...', '2011-08-02 00:11:01.000000', NULL, 1),
(6488237, 964234, 34938, '<td valign="top">pretty impactful...great colour and silhouette 8</td>', 'pretty impactful...great colour and silhouette 8', '2011-08-02 08:17:24.000000', NULL, 1),
(6488242, 964889, 34938, '<td valign="top">Love the sparkles...</td>', 'Love the sparkles...', '2011-08-02 08:28:24.000000', NULL, 1),
(6488243, 964885, 34938, '<td valign="top">great sky</td>', 'great sky', '2011-08-02 08:28:33.000000', NULL, 1),
(6488245, 964339, 34938, '<td valign="top">Great colouring,,,This is obviously Melbourne...where is this taken from? 8</td>', 'Great colouring,,,This is obviously Melbourne...where is this taken from? 8', '2011-08-02 08:32:03.000000', NULL, 1),
(6488275, 964587, 29748, '<td valign="top">I gave you a 5 for the beauty of the overall scene.  I would have scored you higher if it wasnt blurry....Its almost as though you did not use a tripod with the slower shutter speed.</td>', 'I gave you a 5 for the beauty of the overall scene.  I would have scored you higher if it wasnt blurry....Its almost as though you did not use a tripod with the slower shutter speed.', '2011-08-02 09:27:48.000000', NULL, 1),
(6488315, 964487, 92577, '<td valign="top">very dynamic - title sounds like you mean it!</td>', 'very dynamic - title sounds like you mean it!', '2011-08-02 10:18:57.000000', NULL, 1),
(6488636, 964411, 39880, '<td valign="top">I really like this one.  The grain, fog and vignette all work well together.</td>', 'I really like this one.  The grain, fog and vignette all work well together.', '2011-08-02 13:09:45.000000', NULL, 1),
(6488641, 964864, 39880, '<td valign="top">There is sky and there are lines.  Skylines.  Works for me.  And it''s a nicely composed shot.</td>', 'There is sky and there are lines.  Skylines.  Works for me.  And it''s a nicely composed shot.', '2011-08-02 13:11:12.000000', NULL, 1),
(6488646, 964907, 39880, '<td valign="top">Nice outside the box thinking.  I feel that the figure needs some better light on it, and that it (the figure) could be a bit sharper</td>', 'Nice outside the box thinking.  I feel that the figure needs some better light on it, and that it (the figure) could be a bit sharper', '2011-08-02 13:13:40.000000', NULL, 1),
(6488648, 964764, 39880, '<td valign="top">I like how you captured the sun behind the branches.  But overall, I feel the shot lacks impact.</td>', 'I like how you captured the sun behind the branches.  But overall, I feel the shot lacks impact.', '2011-08-02 13:14:41.000000', NULL, 1),
(6488659, 964700, 39880, '<td valign="top">A nice abstract that takes the challenge theme outside the box.  Nice work.</td>', 'A nice abstract that takes the challenge theme outside the box.  Nice work.', '2011-08-02 13:20:04.000000', NULL, 1),
(6488778, 964729, 16106, '<td valign="top">I wish you had gotten down lower for this shot, the subject is a refreshing shift from the big highrise tower at dusk, but the actual horizon line is vague here. There is plenty of interesting stuff to look at, but the skyline itself is played down.</td>', 'I wish you had gotten down lower for this shot, the subject is a refreshing shift from the big highrise tower at dusk, but the actual horizon line is vague here. There is plenty of interesting stuff to look at, but the skyline itself is played down.', '2011-08-02 14:24:36.000000', NULL, 1),
(6488784, 964968, 16106, '<td valign="top">The color cast is pretty jarring here, I wish you had color corrected or de-saturated. Im sure it is what the camera saw, but is it what the eye would percieve?</td>', 'The color cast is pretty jarring here, I wish you had color corrected or de-saturated. Im sure it is what the camera saw, but is it what the eye would percieve?', '2011-08-02 14:27:24.000000', NULL, 1),
(6488788, 964411, 16106, '<td valign="top">Perhaps a bit too strong with the vignette, but I love the perversity of this shot, a strong bi-polar skyline and a rich moody image.</td>', 'Perhaps a bit too strong with the vignette, but I love the perversity of this shot, a strong bi-polar skyline and a rich moody image.', '2011-08-02 14:28:50.000000', NULL, 1),
(6488801, 964939, 16106, '<td valign="top">A lovely shot that probably would have done better in freestudy, since the skyline is one of the least dramatic elements of this complex and complete shot. I particularly like the little wisps of fog on the hills and the reflections in the pond. Nice editing to bring the reds of the barn forward without making it scream.</td>', 'A lovely shot that probably would have done better in freestudy, since the skyline is one of the least dramatic elements of this complex and complete shot. I particularly like the little wisps of fog on the hills and the reflections in the pond. Nice editing to bring the reds of the barn forward without making it scream.', '2011-08-02 14:32:35.000000', NULL, 1),
(6488805, 964835, 16106, '<td valign="top">Of all the flat horizons with dramatic clouds, this is the first to really work. The balance of textures and mood in ground and sky really pull the eye to the horizon. The framing really works with fairly un differentiated grass low and the same level of cloud above, then cutting in the drama in the middle. A subtle drama.</td>', 'Of all the flat horizons with dramatic clouds, this is the first to really work. The balance of textures and mood in ground and sky really pull the eye to the horizon. The framing really works with fairly un differentiated grass low and the same level of cloud above, then cutting in the drama in the middle. A subtle drama.', '2011-08-02 14:35:56.000000', NULL, 1),
(6488809, 964597, 16106, '<td valign="top">I hope the frame doesn''t get you DQed. Nice reduction to architectural scale with a strong dynamic skyline. A bit of noise reduction in the sky would have helped.</td>', 'I hope the frame doesn''t get you DQed. Nice reduction to architectural scale with a strong dynamic skyline. A bit of noise reduction in the sky would have helped.', '2011-08-02 14:38:15.000000', NULL, 1),
(6488849, 964459, 135204, '<td valign="top">Nice colours and interesting composition with the green field leading into the tree line with the city in the background.</td>', 'Nice colours and interesting composition with the green field leading into the tree line with the city in the background.', '2011-08-02 15:01:54.000000', NULL, 1),
(6488856, 964684, 135204, '<td valign="top">Great colour in the sky and reflections in the water.  The exposure of the lights looks spot on.</td>', 'Great colour in the sky and reflections in the water.  The exposure of the lights looks spot on.', '2011-08-02 15:04:49.000000', NULL, 1),
(6488860, 964313, 135204, '<td valign="top">Good colours in the sky and nice capture of light streaks on the road.</td>', 'Good colours in the sky and nice capture of light streaks on the road.', '2011-08-02 15:06:33.000000', NULL, 1),
(6488864, 964697, 135204, '<td valign="top">Cool cloudscape, very moody.</td>', 'Cool cloudscape, very moody.', '2011-08-02 15:08:41.000000', NULL, 1),
(6488868, 964699, 135204, '<td valign="top">Looks very gray and Gothamesque, like it.</td>', 'Looks very gray and Gothamesque, like it.', '2011-08-02 15:09:46.000000', NULL, 1),
(6488871, 964824, 135204, '<td valign="top">Intersting lines and light.</td>', 'Intersting lines and light.', '2011-08-02 15:10:48.000000', NULL, 1),
(6488872, 964858, 135204, '<td valign="top">Super colours in the sky and water.</td>', 'Super colours in the sky and water.', '2011-08-02 15:11:24.000000', NULL, 1),
(6488880, 964478, 135204, '<td valign="top">Good compositon but looks slightly under exposed to me.  I think a bump in exposure would bring out lots of detail in the trees and some in the sky too.</td>', 'Good compositon but looks slightly under exposed to me.  I think a bump in exposure would bring out lots of detail in the trees and some in the sky too.', '2011-08-02 15:14:14.000000', NULL, 1),
(6488884, 964603, 135204, '<td valign="top">Nice blurred sky.  I would love to see a larger version of this because I have a feeling there is a lot of detail lost in the buildings at this size.</td>', 'Nice blurred sky.  I would love to see a larger version of this because I have a feeling there is a lot of detail lost in the buildings at this size.', '2011-08-02 15:15:42.000000', NULL, 1),
(6488888, 964317, 135204, '<td valign="top">Wow!!! Amazing shot, this deserves a ribbon.</td>', 'Wow!!! Amazing shot, this deserves a ribbon.', '2011-08-02 15:16:10.000000', NULL, 1),
(6488889, 964234, 135204, '<td valign="top">Truly an excellent shot, one of my top picks.</td>', 'Truly an excellent shot, one of my top picks.', '2011-08-02 15:16:15.000000', NULL, 1),
(6488914, 964861, 135204, '<td valign="top">Nice colour shift in the sky and blur in the water.</td>', 'Nice colour shift in the sky and blur in the water.', '2011-08-02 15:26:40.000000', NULL, 1),
(6488922, 964326, 135204, '<td valign="top">Nice lighting capture.  Personally I would have cropped out some of the water at the bottom.</td>', 'Nice lighting capture.  Personally I would have cropped out some of the water at the bottom.', '2011-08-02 15:29:29.000000', NULL, 1),
(6488926, 964396, 135204, '<td valign="top">I like the compostion and the reflections in the water.</td>', 'I like the compostion and the reflections in the water.', '2011-08-02 15:30:36.000000', NULL, 1),
(6488941, 964623, 135204, '<td valign="top">At first this didn''t speak to me, but looking at it again there is something very human about the shot.  It is like picturing the memory of a perfect summer day in your mind but like most memories not being able to focus on the details.  Excellent.</td>', 'At first this didn''t speak to me, but looking at it again there is something very human about the shot.  It is like picturing the memory of a perfect summer day in your mind but like most memories not being able to focus on the details.  Excellent.', '2011-08-02 15:42:18.000000', NULL, 1),
(6488947, 964597, 135204, '<td valign="top">Nice use of grain.  I''m not normally a fan of borders but this one seems to work with this shot.</td>', 'Nice use of grain.  I''m not normally a fan of borders but this one seems to work with this shot.', '2011-08-02 15:44:17.000000', NULL, 1),
(6488949, 964611, 135204, '<td valign="top">Intersing colours, it looks like the trees above the house are about to burst into flames.</td>', 'Intersing colours, it looks like the trees above the house are about to burst into flames.', '2011-08-02 15:46:32.000000', NULL, 1),
(6488951, 964949, 135204, '<td valign="top">Good city shot but seems somewhat under exposed.</td>', 'Good city shot but seems somewhat under exposed.', '2011-08-02 15:48:13.000000', NULL, 1),
(6488965, 964002, 135204, '<td valign="top">I like how the sun is just out of the shot.  Nice colours.</td>', 'I like how the sun is just out of the shot.  Nice colours.', '2011-08-02 15:51:42.000000', NULL, 1),
(6488974, 964637, 135204, '<td valign="top">Great silhouette and love how the sun is behind the cloud.</td>', 'Great silhouette and love how the sun is behind the cloud.', '2011-08-02 15:54:15.000000', NULL, 1),
(6488980, 964488, 135204, '<td valign="top">Excellent exposure and love the star burst lights on the right.</td>', 'Excellent exposure and love the star burst lights on the right.', '2011-08-02 15:55:51.000000', NULL, 1),
(6489016, 963948, 16106, '<td valign="top">Nice collection of forms, but they don''t really hang together to create a single skyline. If you could have moved left and squeezed them closer together to have less empty space around each form it would hold more excitement for me.</td>', 'Nice collection of forms, but they don''t really hang together to create a single skyline. If you could have moved left and squeezed them closer together to have less empty space around each form it would hold more excitement for me.', '2011-08-02 16:24:40.000000', NULL, 1),
(6489019, 964487, 16106, '<td valign="top">Nice dynamic shot with a good mix of colors, my pick for blue</td>', 'Nice dynamic shot with a good mix of colors, my pick for blue', '2011-08-02 16:27:01.000000', NULL, 1),
(6489021, 964851, 16106, '<td valign="top">Looks a bit too aggressive with the tone mapping or shadow repair, you have lost a bit too much contrast. I like the processional quality of the people juxtaposed with the lamp posts in the same arc.</td>', 'Looks a bit too aggressive with the tone mapping or shadow repair, you have lost a bit too much contrast. I like the processional quality of the people juxtaposed with the lamp posts in the same arc.', '2011-08-02 16:29:30.000000', NULL, 1),
(6489030, 964688, 16106, '<td valign="top">Lovely juxtaposition of man made and natural, though the low saturation puzzles me. I can imagine this working better in pure B&amp;W or fully saturated. As is is just seem understated.</td>', 'Lovely juxtaposition of man made and natural, though the low saturation puzzles me. I can imagine this working better in pure B&W or fully saturated. As is is just seem understated.', '2011-08-02 16:32:21.000000', NULL, 1),
(6489033, 964339, 16106, '<td valign="top">The composition is stunning, but the soft contrast and saturation, mixed with the odd colorspace steal a lot of the drama.</td>', 'The composition is stunning, but the soft contrast and saturation, mixed with the odd colorspace steal a lot of the drama.', '2011-08-02 16:34:49.000000', NULL, 1),
(6489041, 964317, 16106, '<td valign="top">Not the most impressive skyline, but you made the most of it. Very deft handling of a huge DOF and radical contrast issues to make a pleasing densely texture shot.</td>', 'Not the most impressive skyline, but you made the most of it. Very deft handling of a huge DOF and radical contrast issues to make a pleasing densely texture shot.', '2011-08-02 16:37:40.000000', NULL, 1),
(6489082, 964881, 16106, '<td valign="top">A classic view (and not the only version of this iconic skyline in this challenge) and Im torn on the processing. On one hand I like the candy colored old timey postcard feel, but it looses some of the depth in the image. The brig''s fore mast is almost lost against the buildings, and the towers that make up the skyline are flattened out, and the yellow on the building on the left is jarring against the overall blue tone. If you had brought up the black point, it might separate the two tones a bit more.<br/> <br/>I know it sounds like Im picking on the image, but I really like it and given the direction you went, I think it works. Top five</td>', 'A classic view (and not the only version of this iconic skyline in this challenge) and Im torn on the processing. On one hand I like the candy colored old timey postcard feel, but it looses some of the depth in the image. The brig''s fore mast is almost lost against the buildings, and the towers that make up the skyline are flattened out, and the yellow on the building on the left is jarring against the overall blue tone. If you had brought up the black point, it might separate the two tones a bit more. I know it sounds like Im picking on the image, but I really like it and given the direction you went, I think it works. Top five', '2011-08-02 17:02:42.000000', NULL, 1),
(6489118, 964864, 56502, '<td valign="top">Interesting take on the topic.</td>', 'Interesting take on the topic.', '2011-08-02 17:27:35.000000', NULL, 1),
(6489177, 964892, 126181, '<td valign="top">its a bit to dark, if you brightened it up a bit, it would make this so much better.</td>', 'its a bit to dark, if you brightened it up a bit, it would make this so much better.', '2011-08-02 17:57:38.000000', NULL, 1),
(6489179, 964452, 126181, '<td valign="top">wow! I love this.</td>', 'wow! I love this.', '2011-08-02 17:58:12.000000', NULL, 1),
(6489182, 964587, 126181, '<td valign="top">I like the reflection in the water, very nice.</td>', 'I like the reflection in the water, very nice.', '2011-08-02 17:58:48.000000', NULL, 1),
(6489185, 964326, 126181, '<td valign="top">amazing.</td>', 'amazing.', '2011-08-02 17:59:07.000000', NULL, 1),
(6489187, 964297, 126181, '<td valign="top">I love the colour in this, its perfect.</td>', 'I love the colour in this, its perfect.', '2011-08-02 17:59:43.000000', NULL, 1),
(6489191, 964684, 126181, '<td valign="top">I adore these types of photos, very lively and bright, well done.</td>', 'I adore these types of photos, very lively and bright, well done.', '2011-08-02 18:00:44.000000', NULL, 1),
(6489196, 964317, 126181, '<td valign="top">That just doesn''t look real at all, thats like a dream world, but I like it.</td>', 'That just doesn''t look real at all, thats like a dream world, but I like it.', '2011-08-02 18:01:38.000000', NULL, 1),
(6489200, 964851, 126181, '<td valign="top">Its to sharp it makes the picture look fake, I don''t like it.</td>', 'Its to sharp it makes the picture look fake, I don''t like it.', '2011-08-02 18:02:21.000000', NULL, 1),
(6489203, 964889, 126181, '<td valign="top">I like all the blues and greens in this, it makes the photo.</td>', 'I like all the blues and greens in this, it makes the photo.', '2011-08-02 18:03:25.000000', NULL, 1),
(6489207, 964890, 126181, '<td valign="top">That looks like two completely diffrent world on the flower side it looks like summer and then the mountain side looks like winter, however I like the photo.</td>', 'That looks like two completely diffrent world on the flower side it looks like summer and then the mountain side looks like winter, however I like the photo.', '2011-08-02 18:06:02.000000', NULL, 1),
(6489276, 964419, 38930, '<td valign="top">Here''s a winner! Awesome shot</td>', 'Here''s a winner! Awesome shot', '2011-08-02 18:40:41.000000', NULL, 1),
(6489277, 964950, 38930, '<td valign="top">Great colors!</td>', 'Great colors!', '2011-08-02 18:40:47.000000', NULL, 1),
(6489278, 964670, 38930, '<td valign="top">Awesome silhouette and the colors are perfect</td>', 'Awesome silhouette and the colors are perfect', '2011-08-02 18:41:15.000000', NULL, 1),
(6489279, 964816, 38930, '<td valign="top">Great picture and awesome title</td>', 'Great picture and awesome title', '2011-08-02 18:41:33.000000', NULL, 1),
(6489282, 964929, 38930, '<td valign="top">This would be a much stronger picture if it wasn''t tilted. Love this place though and it''s a really nice shot... not a picture you usually see from Niagara.</td>', 'This would be a much stronger picture if it wasn''t tilted. Love this place though and it''s a really nice shot... not a picture you usually see from Niagara.', '2011-08-02 18:42:29.000000', NULL, 1),
(6489283, 964698, 38930, '<td valign="top">Seems a little dark, but it definitely helps the guy in the middle stand out</td>', 'Seems a little dark, but it definitely helps the guy in the middle stand out', '2011-08-02 18:42:51.000000', NULL, 1),
(6489285, 964490, 38930, '<td valign="top">Great colors!</td>', 'Great colors!', '2011-08-02 18:43:10.000000', NULL, 1),
(6489286, 964862, 38930, '<td valign="top">This is really nice!</td>', 'This is really nice!', '2011-08-02 18:43:22.000000', NULL, 1),
